import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { site } from '@/config/site';
import { LOGO_URL } from './json-ld';

// The brand images in public/ are generated by scripts/brand (D-289). These tests guard what a
// browser or a store relies on: the sizes, the formats and that the manifest names real files.
const PUBLIC = fileURLToPath(new URL('../../public/', import.meta.url));
const read = (name: string) => readFileSync(`${PUBLIC}${name}`);

function pngSize(name: string): [number, number] {
  const data = read(name);
  expect(data.subarray(1, 4).toString(), `${name} is a PNG`).toBe('PNG');
  return [data.readUInt32BE(16), data.readUInt32BE(20)];
}

describe('the app icons', () => {
  it.each([
    ['apple-touch-icon.png', 180],
    ['icon-192.png', 192],
    ['icon-512.png', 512],
    ['icon-maskable-512.png', 512],
    ['brand/logo-512.png', 512],
  ])('%s is a %i pixel square', (name, size) => {
    expect(pngSize(name)).toEqual([size, size]);
  });

  it('keeps transparency only where the icon is meant to float, never on an app icon plate', () => {
    // PNG colour type 6 is RGBA, 2 is RGB: the plates must be opaque, since iOS paints black behind
    // any transparency and a maskable icon must fill its whole square.
    const colourType = (name: string) => read(name)[25];
    expect(colourType('apple-touch-icon.png')).toBe(2);
    expect(colourType('icon-maskable-512.png')).toBe(2);
    expect(colourType('brand/logo-512.png')).toBe(6);
  });
});

describe('favicon.ico', () => {
  it('holds PNG images of 16, 32 and 48 pixels', () => {
    const ico = read('favicon.ico');
    expect(ico.readUInt16LE(2)).toBe(1); // an icon, not a cursor
    const count = ico.readUInt16LE(4);
    const found: number[] = [];
    for (let i = 0; i < count; i += 1) {
      const entry = 6 + i * 16;
      const size = ico[entry] ?? 0;
      const offset = ico.readUInt32LE(entry + 12);
      expect(ico.subarray(offset + 1, offset + 4).toString()).toBe('PNG');
      expect(ico.readUInt32BE(offset + 16)).toBe(size);
      found.push(size);
    }
    expect(found).toEqual([16, 32, 48]);
  });
});

describe('the SVG files', () => {
  it.each([
    'icon.svg',
    'brand/mark.svg',
    'brand/mark-on-dark.svg',
    'brand/mark-mono-black.svg',
    'brand/mark-mono-white.svg',
  ])('%s is a standalone drawing with a view box, no script and no outside reference', (name) => {
    const svg = read(name).toString('utf8');
    expect(svg.startsWith('<svg ')).toBe(true);
    expect(svg).toMatch(/viewBox="[\d. -]+"/);
    expect(svg).not.toMatch(/<script|<image|<foreignObject|href=|xlink:/i);
  });

  it('lets the tab icon scale: no fixed width or height on the root', () => {
    const root = /^<svg[^>]*>/.exec(read('icon.svg').toString('utf8'))?.[0] ?? '';
    expect(root).not.toMatch(/\swidth=|\sheight=/);
  });

  it('switches the arrowhead face to gold on a dark browser theme', () => {
    const svg = read('icon.svg').toString('utf8');
    expect(svg).toContain('prefers-color-scheme:dark');
  });
});

describe('the web manifest', () => {
  const manifest = JSON.parse(read('manifest.webmanifest').toString('utf8')) as {
    name: string;
    theme_color: string;
    background_color: string;
    icons: { src: string; sizes: string; type: string; purpose: string }[];
  };

  it('names the site and uses the brand black', () => {
    expect(manifest.name).toBe(site.name);
    expect(manifest.theme_color).toBe('#000000');
    expect(manifest.background_color).toBe('#000000');
  });

  it('lists only files that exist, with the sizes they really have', () => {
    for (const icon of manifest.icons) {
      const file = icon.src.replace(/^\//, '');
      expect(() => read(file), icon.src).not.toThrow();
      if (icon.type === 'image/png') {
        const [w, h] = pngSize(file);
        expect(icon.sizes).toBe(`${String(w)}x${String(h)}`);
      }
    }
  });

  it('offers a 192 and a 512 icon for any use and a maskable one', () => {
    const any = manifest.icons.filter((i) => i.purpose === 'any').map((i) => i.sizes);
    expect(any).toEqual(expect.arrayContaining(['192x192', '512x512']));
    expect(manifest.icons.some((i) => i.purpose === 'maskable')).toBe(true);
  });
});

describe('the logo in structured data', () => {
  it('is an address on the site that points at a real, square, large enough image', () => {
    expect(LOGO_URL.startsWith(`${site.origin}/`)).toBe(true);
    const [w, h] = pngSize(LOGO_URL.slice(site.origin.length + 1));
    expect(w).toBe(h);
    expect(w).toBeGreaterThanOrEqual(112);
  });
});
